log = function (msg) {
  popData.count += 1;
  return console.log(`Popup Msg ${popData.count} : ${msg}`);
};
isChrome = function () {
  return navigator.userAgent.indexOf("Chrome") > -1;
};
fixPos = function (sel, e) {
  var eventLeft, eventTop, fix, m_left, offsetLeft, offsetTop, offsets;
  offsets = get_selection_offsets(sel, e);
  offsetTop = offsets[0];
  offsetLeft = offsets[1];
  if (e != null) {
    eventTop = e.pageY;
    eventLeft = e.pageX;
    //log offsetTop + " : " + offsetLeft + " <==> " + eventTop + " : " + eventLeft
    if (Math.abs(offsetTop - eventTop) > 50) {
      offsetTop = eventTop - 10;
    } else {
      offsetTop = Math.min(eventTop - 10, offsetTop);
    }
    if (Math.abs(offsetLeft - eventLeft) > 50) {
      //translate
      offsetLeft = eventLeft + 10;
    }
  } else {
    $('#showUpBody').css('margin-left', '60px');
  }
  if (GetOpt('Dis_st')) {
    //UpSide
    offsetTop = offsetTop - 4 - $('#ShowUpBox').height();
    if (offsetTop - document.documentElement.scrollTop < 40) {
      offsetTop = document.documentElement.scrollTop + 40;
    }
  } else {
    offsetTop += 1.1 * offsets[2];
  }
  m_left = $('#ShowUpBox').width();
  fix = 0;
  if (offsetLeft - m_left < 4) {
    fix = 4 - offsetLeft + m_left;
  }
  $('#ShowUpBox').css("top", offsetTop + "px").css("left", offsetLeft - m_left + fix + "px");
  return $('#popupTip').css('margin-left', m_left - 20 - fix);
};


var getOrderedEngines = function () {
  var allEngines = [];
  var engineMap = {};
  var j, engine;
  for (j = 0; j < popData.engines.length; j++) {
    engine = popData.engines[j];
    engineMap[engine.id] = engine;
  }
  if (popData.userEngines && popData.userEngines.length) {
    for (j = 0; j < popData.userEngines.length; j++) {
      engine = popData.userEngines[j];
      engine.isCustom = true;
      engineMap[engine.id] = engine;
    }
  }
  var savedOrder = GM_getValue("engineOrder", null);
  if (savedOrder && Array.isArray(savedOrder)) {
    var addedIds = {};
    for (j = 0; j < savedOrder.length; j++) {
      var id = savedOrder[j];
      if (engineMap[id]) {
        allEngines.push(engineMap[id]);
        addedIds[id] = true;
      }
    }
    for (j = 0; j < popData.engines.length; j++) {
      engine = popData.engines[j];
      if (!addedIds[engine.id]) {
        allEngines.push(engine);
        addedIds[engine.id] = true;
      }
    }
    if (popData.userEngines) {
      for (j = 0; j < popData.userEngines.length; j++) {
        engine = popData.userEngines[j];
        if (!addedIds[engine.id]) {
          allEngines.push(engine);
          addedIds[engine.id] = true;
        }
      }
    }
  } else {
    allEngines = popData.engines.concat(popData.userEngines || []);
  }
  return allEngines;
};

PopupInit = function () {
  var $DivBox, $icon, EngineList, engine, j, len, orderedEngines;
  $('#ShowUpBox').remove();
  EngineList = "";
  orderedEngines = getOrderedEngines();
  for (j = 0, len = orderedEngines.length; j < len; j++) {
    engine = orderedEngines[j];
    var cls = engine.isCustom ? 'userEngine' : 'engine';
    EngineList += `<a id='${engine.id}Icon' class='${cls}' title='${engine.title}'><img title='${engine.title}' src='${engine.src}' /></a>`;
  }
  $('html').append(`<span id="ShowUpBox"> <span id="showUpBody"> <span id="popupWrapper"> ${EngineList} </span> <span id="transPanel" /> </span> </span>`);
  $DivBox = $('#ShowUpBox');
  $DivBox.hide();
  $DivBox.on("click dblclick mousedown mouseup contextmenu", function (event) {
    return event.stopPropagation();
  });
  $('#transPanel').on("mouseup contextmenu", function (event) {
    return event.stopPropagation();
  });
  // Apply front-end display count preference
  var displayMode = GM_getValue("engineDisplayMode", "default");
  if (displayMode === 'all') {
    $('#popupWrapper').css({
      'max-width': 'none',
      'overflow-x': 'visible'
    });
  } else {
    var displayCount = 8;
    if (displayMode === 'custom') {
      displayCount = parseInt(GM_getValue("engineDisplayCount", 8), 10) || 8;
      displayCount = Math.max(1, Math.min(50, displayCount));
    }
    // Each icon: 26px width + 3px gap = 29px. N icons: N * 29 - 3 + 4 = N * 29 + 1
    var maxWidth = (displayCount * 29 + 2) + 'px';
    $('#popupWrapper').css({
      'max-width': maxWidth,
      'overflow-x': 'auto',
      'overflow-y': 'hidden'
    });
  }

  // Enable horizontal smooth mouse wheel scrolling for popupWrapper
  $('#popupWrapper').on('wheel', function (event) {
    var delta = event.originalEvent.deltaY || event.originalEvent.deltaX;
    if (delta !== 0) {
      this.scrollLeft += delta;
      event.preventDefault();
      event.stopPropagation();
    }
  });
  $DivBox.hover(function () {
    $(this).fadeTo(150, 1);
    return popData.mouseIn = 1;
  }, function () {
    if (popData.bTrans === 0 && $(this).is(":visible") && $(this).attr("opacity") === 1) {
      $(this).fadeTo(300, 0.7);
    }
    return popData.mouseIn = 0;
  });
  $('#showUpBody').on("mouseup", function (event) {
    if (event.which === 3) {
      CopyText();
      hideBar(100);
      return false;
    } else if (event.which === 2) {
      GM_openInTab(document.defaultView.getSelection().toString());
      return false;
    }
  });
  $('#showUpBody').on("contextmenu", function (event) {
    return false;
  });
  for (j = 0, len = orderedEngines.length; j < len; j++) {
    engine = orderedEngines[j];
    $icon = $("#" + engine.id + "Icon");
    if (!GetOpt(engine.id)) {
      $icon.hide();
    }
  }
  $DivBox.find('.userEngine').on('click', OnEngine);
  if (GetOpt('Tab_st')) {
    $DivBox.find('a').attr('target', '_blank');
  } else {
    $DivBox.find('a').attr('target', '_self');
  }
  if (GetOpt('Dis_st')) {
    popData.tip = popData.tipUp;
    return $DivBox.append('<span id="popupTip" class="tipUp"></span>');
  } else {
    popData.tip = popData.tipDown;
    return $DivBox.prepend('<span id="popupTip" class="tipDown"></span>');
  }
};

ajaxError = function (res) {
  return $('#transPanel').empty().append(`<p>Translate Error:<br /> ${res.statusText} </p>`).show();
};
onCopy = function () {
  CopyText();
  return hideBar();
};
onTranslate = function (engine) {
  popData.bTrans = 1;
  $("#transPanel").empty().append(`<div style='padding:10px;'><img src='${popData.icons.pending}' /></div>`).show();
  $('#popupWrapper').hide();
  fixPos(document.defaultView.getSelection());
  return doRequest(engine, 0, 2000);
};
doRequest = function (engine, i, wait) {
  var ErrHandle, lang, requestData;
  ErrHandle = function () {
    return doRequest(engine, i + 1, wait + 2000);
  };
  if (i >= 2) {
    ErrHandle = ajaxError;
  }
  lang = navigator.language || navigator.userLanguage || "zh-CN";
  if (engine === 'google') {
    return GM_xmlhttpRequest({
      method: 'POST',
      url: `https://translate.google.com/translate_a/single?client=gtx&dj=1&q=${popData.text}&sl=auto&tl=${lang}&hl=${lang}&ie=UTF-8&oe=UTF-8&source=icon&dt=t&dt=bd`,
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
        "Accept-Encoding": "gzip, deflate"
      },
      timeout: wait,
      onload: parseTranslationGoogle,
      onerror: ErrHandle,
      ontimeout: ErrHandle
    });
  } else if (engine === 'deepl') {
    return GM_xmlhttpRequest({
      method: 'POST',
      url: "https://api-free.deepl.com/v2/translate??auth_key=aa09f88d-ab75-3488-b8a3-18ad27a35870:fx",
      data: "auth_key=aa09f88d-ab75-3488-b8a3-18ad27a35870:fx&target_lang=ZH&text=" + popData.rawText,
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded'
      },
      timeout: wait,
      onload: parseTranslationDeepl,
      onerror: ErrHandle,
      ontimeout: ErrHandle
    });
  } else if (engine === 'deeplx') {
    requestData = {
      text: popData.rawText,
      source_lang: 'auto',
      target_lang: 'zh'
    };
    return GM_xmlhttpRequest({
      method: 'POST',
      url: "https://fw4dxxj9tn.us.aircode.run/translate",
      headers: {
        'Content-Type': 'application/json'
      },
      data: JSON.stringify(requestData),
      timeout: wait,
      onload: parseTranslationDeeplX,
      onerror: ErrHandle,
      ontimeout: ErrHandle
    });
  } else {
    return GM_xmlhttpRequest({
      method: 'POST',
      url: "http://api.interpreter.caiyunai.com/v1/translator",
      headers: {
        'Content-Type': 'application/json',
        "X-Authorization": "token " + "3975l6lr5pcbvidl6jl2"
      },
      data: JSON.stringify({
        "source": [popData.rawText],
        "trans_type": "auto2zh",
        "request_id": "demo",
        "detect": true
      }),
      timeout: wait,
      onload: parseTranslationCaiyun,
      onerror: ErrHandle,
      ontimeout: ErrHandle
    });
  }
};
